using System;using System.IO;using System.Linq;using Purrington.Domain;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
class MemoryStore:ISaveStore{public bool fail;public HotelState state;public HotelState Load()=>state==null?null:HotelModel.Copy(state);public bool Save(HotelState s){if(fail)return false;state=HotelModel.Copy(s);return true;}}
class Program{
 static int checks;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}static JObject P(string json)=>JObject.Parse(json);
 static void Main(string[] args){TownSuites.Run(Check);TownCommerceSuites.Run(Check);TownEventSuites.Run(Check);if(args.Length>0&&args[0]=="town"){Console.WriteLine("PASS "+checks+" town checks");return;}var content=ParityContent.LoadJson(File.ReadAllText("unity/PurringtonHotel/Assets/Resources/Content/GodotReference.json"));if(args.Length>0&&args[0]=="wardrobe"){WardrobeSuites.RunWardrobe(Check,P,content);Console.WriteLine("PASS "+checks+" wardrobe checks");return;}var store=new MemoryStore();var m=new HotelModel(store,content);Check(m.LoadOrCreate().success,"starter saves");Check(HotelModel.Valid(m.State),"starter structurally valid");Check(Catalog.All.Length==38&&content.Templates.Length==6&&content.Maps.Length==4,"complete content");Check(m.State.cats.Count==18&&m.State.cats.Count(c=>c.known)==4,"source roster");for(int i=0;i<4;i++){Check(m.Hotel(i).rooms.Count==content.Starter["hotels"][i]["rooms"].Count(),"map room equivalence");Check(m.Hotel(i).objects.Count==content.Starter["hotels"][i]["objects"].Count(),"map object equivalence");Console.WriteLine("Map "+i+" capacity "+m.GuestCapacity(i)+" rate "+m.Rate(i));}Check(m.GuestCapacity()>0,"starter accessible beds");double rate=m.Rate();Check(rate>0,"starter produces income");string before=JsonConvert.SerializeObject(m.State);m.Quote("place_room",P("{x:500,y:500}"));Check(before==JsonConvert.SerializeObject(m.State),"failed quote immutable");m.Quote("upgrade",P("{service:0}"));Check(before==JsonConvert.SerializeObject(m.State),"successful quote immutable");store.fail=true;Check(!m.Execute("upgrade",P("{service:0}")).success,"save failure rejects upgrade");Check(before==JsonConvert.SerializeObject(m.State),"save failure rollback");store.fail=false;
 Check(m.Care(0,m.State.cats[0].favoriteAction).success,"favorite care");Check(m.State.cats[0].bond==6,"favorite six");m.Care(0,"Pet");Check(m.State.cats[0].bond==6,"care cooldown");m.State.elapsed+=12;m.Care(0,m.State.cats[0].favoriteAction=="pet"?"brush":"pet");Check(m.State.cats[0].bond==9,"ordinary three");m.State.cats[0].bond=99;m.State.elapsed+=12;m.Care(0,"Pet");Check(m.State.cats[0].bond==100,"friendship cap");
 double coins=m.State.coins;Check(m.Execute("upgrade",P("{service:0}")).success,"upgrade purchase");Check(Math.Abs(coins-m.State.coins-Math.Round(240*Math.Pow(2,1/3.0)))<.01,"source upgrade price");m.State.coins+=17;m.State.cats[1].bond=11;Check(m.Undo().success,"undo succeeds");Check(m.State.coins==coins+17&&m.State.cats[1].bond==11,"undo preserves earnings and friendship");Check(m.Redo().success,"redo succeeds");
  var seaside=new HotelModel(new MemoryStore(),content);seaside.LoadOrCreate();var gate=seaside.CanTravel(1);Check(!gate.success&&gate.cost==10000,"seaside gate level");seaside.Hotel(0).level=10;seaside.State.coins=9999;gate=seaside.CanTravel(1);Check(!gate.success&&gate.cost==10000&&gate.message.Contains("10,000"),"seaside gate coins");seaside.State.coins=15000;gate=seaside.CanTravel(1);Check(gate.success&&gate.cost==10000,"seaside gate ready");Check(seaside.Travel(1).success&&seaside.State.coins==5000&&seaside.Hotel(1).owned&&seaside.State.currentHotel==1,"seaside travel unlock");var round=new NewtonsoftSaveCodec().Deserialize(new NewtonsoftSaveCodec().Serialize(seaside.State));Check(HotelModel.Valid(round)&&round.hotels[1].owned&&round.currentHotel==1&&round.coins==5000,"seaside save roundtrip");
 Check(m.SetGodMode(true).success,"God mode");Check(m.State.hotels.All(h=>h.owned)&&m.State.cats.All(c=>c.known)&&m.State.entitlements.Count==3,"God unlocks full content");for(int i=0;i<4;i++)Check(m.Travel(i).success,"travel all maps");Check(m.Travel(0).success,"return meadow");
 foreach(var t in content.Templates)for(int rotation=0;rotation<4;rotation++){var scratch=new HotelModel(new MemoryStore(),content);scratch.LoadOrCreate();scratch.SetGodMode(true);scratch.Hotel().rooms.Clear();scratch.Hotel().floors.Clear();scratch.Hotel().objects.Clear();var map=content.Maps[0];var bounds=map["base"];var p=new JObject{{"template",t["id"]},{"x",(int)bounds[0]+2},{"y",(int)bounds[1]+2},{"rotation",rotation}};var result=scratch.Execute("place_template",p);Check(result.success,"template "+t["id"]+" rotation "+rotation+": "+result.message);Check(scratch.State.objects.Count==t["objects"].Count(),"template children preserved");Check(scratch.State.objects.All(o=>o.paid==0)&&scratch.State.rooms[0].paid==0,"God paid records zero");}
 m.State.lastSeen=1000;m.State.pendingCoins=0;rate=m.Rate();Check(m.Reconcile(1000+40000).success,"offline reconcile");Check(Math.Abs(m.State.pendingCoins-rate*480)<.01,"offline eight hour cap");double pending=m.State.pendingCoins;coins=m.State.coins;store.fail=true;Check(!m.ClaimOffline().success&&m.State.pendingCoins==pending&&m.State.coins==coins,"offline claim rollback");store.fail=false;Check(m.ClaimOffline().success&&m.State.pendingCoins==0,"offline claim");
 var live=new HotelModel(new MemoryStore(),content);live.LoadOrCreate();for(int t=0;t<3000;t++){live.Tick(.2f);foreach(var a in live.Actors){Check(live.CanWalk(a.x,a.z),"actor geometry safe "+a.name);foreach(var b in live.Actors.Where(b=>String.CompareOrdinal(b.id,a.id)>0))Check(new LotPoint(a.x,a.z).Distance(new LotPoint(b.x,b.z))>=.719f,"actor separation");}}Check(live.Actors.Count>0,"authoritative actor roster");Console.WriteLine("Life visits "+live.Hotel().visits+" actors "+live.Actors.Count);
 var denseSeed=content.CreateState();var dh=denseSeed.hotels[0];dh.plots=new System.Collections.Generic.List<string>{"west","east","north"};dh.rooms.Clear();dh.floors.Clear();dh.objects.Clear();dh.paths.Clear();dh.level=10;dh.maid=true;for(int i=0;i<24;i++){int x=-20+i%6*6,z=-12+i/6*6;string id="dense-room-"+i;dh.rooms.Add(new RoomState{id=id,name="Garden cottage "+i,x=x,z=z,width=4,depth=3});var pieces=new[]{("mat",.5f,.5f),("box",2.5f,.5f),("plant",3.5f,2.5f),("lamp",.5f,2.5f)};foreach(var piece in pieces)dh.objects.Add(new ObjectState{id=id+"-"+piece.Item1,itemId=piece.Item1,room=id,x=x+piece.Item2,z=z+piece.Item3});dh.dirty[id]=true;}dh.rooms.Add(new RoomState{id="dense-lobby",kind="shared",name="Courtyard lobby",x=-10,z=-19,width=6,depth=6});dh.objects.Add(new ObjectState{id="dense-reception",itemId="reception_counter",room="dense-lobby",x=-9.5f,z=-18.5f});dh.objects.Add(new ObjectState{id="dense-sofa",itemId="lounge_sofa",room="dense-lobby",x=-9.5f,z=-15.5f});for(int x=-20;x<20;x++)for(int z=-20;z<12;z++){bool owned=new[]{content.Maps[0]["base"]}.Concat(content.Maps[0]["plots"].Where(p=>dh.plots.Contains((string)p["id"])).Select(p=>p["rect"])).Any(b=>x>=(float)b[0]&&z>=(float)b[1]&&x+1<=(float)b[0]+(float)b[2]&&z+1<=(float)b[1]+(float)b[3]);if(owned)dh.paths[x+","+z]=new PathState();}foreach(var c in denseSeed.cats)c.known=true;var denseStore=new MemoryStore{state=denseSeed};var dense=new HotelModel(denseStore,content);Check(dense.LoadOrCreate().success,"dense restores");Check(dense.GuestCapacity()==48,"all 24 cottages accessible");Check(dense.State.objects.Count==98,"98 dense objects");var stopwatch=System.Diagnostics.Stopwatch.StartNew();int maxGuests=0;for(int tick=0;tick<3000;tick++){dense.Tick(.2f);var snapshot=dense.Actors;maxGuests=Math.Max(maxGuests,snapshot.Count(a=>a.catId<1000));foreach(var a in snapshot){Check(dense.CanWalk(a.x,a.z),"dense actor body geometry "+a.id);foreach(var b in snapshot.Where(b=>String.CompareOrdinal(b.id,a.id)>0))Check(new LotPoint(a.x,a.z).Distance(new LotPoint(b.x,b.z))>=.719f,"dense body separation "+a.id+" "+b.id);}}stopwatch.Stop();Check(maxGuests==18,"dense admits all 18 cats");Check(dense.Hotel().cleaned>0,"dense housekeeper completes work");Check(dense.Hotel().visits>0,"dense activities finish");Console.WriteLine("Dense 600s: "+dense.Hotel().visits+" visits, "+dense.Hotel().cleaned+" cleaned, "+maxGuests+" guests, "+stopwatch.ElapsedMilliseconds+"ms CPU");
var oracle=JObject.Parse(File.ReadAllText("unity/PurringtonHotel/Assets/Resources/Content/GodotOracle.json"));var oracleModel=new HotelModel(new MemoryStore(),content);oracleModel.LoadOrCreate();foreach(var map in oracle["maps"]){oracleModel.State.currentHotel=(int)map["index"];Check(oracleModel.Rate()==(double)map["rate"],"oracle total rate");Check(oracleModel.GuestCapacity()==(int)map["capacity"],"oracle capacity");foreach(var rs in map["statuses"]){var status=oracleModel.RoomStatus((string)rs["id"]);Check(status.ready==(bool)rs["status"]["ready"]&&status.status==(string)rs["status"]["status"],"oracle room status");}}oracleModel=new HotelModel(new MemoryStore(),content);oracleModel.LoadOrCreate();oracleModel.State.coins=100000;foreach(var step in oracle["construction"]){string action=(string)step["action"];var p=(JObject)step["payload"];if(step["quote"]!=null){var quote=oracleModel.Quote(action,p);Check(quote.success==(bool)step["quote"]["ok"]&&quote.cost==(double)step["quote"]["cost"],"oracle quote "+action);}var result=action=="undo"?oracleModel.Undo():oracleModel.Execute(action,p);Check(result.success==(bool)step["result"]["ok"]&&result.cost==(double)step["result"]["cost"],"oracle command "+action);var after=step["after"];Check(oracleModel.State.coins==(double)after["coins"],"oracle wallet "+action);Check(oracleModel.GuestCapacity()==(int)after["capacity"],"oracle access "+action);Check(oracleModel.Rate()==(double)after["rate"],"oracle rate "+action);Check(oracleModel.State.rooms.Count==after["rooms"].Count()&&oracleModel.State.objects.Count==after["objects"].Count(),"oracle layout count "+action);foreach(var raw in after["objects"]){var obj=oracleModel.State.objects.Single(o=>o.id==(string)raw["id"]);Check(obj.x==(float)raw["x"]&&obj.z==(float)raw["y"]&&obj.rotation==(int)raw["rotation"]&&obj.paid==(double)raw["paid"]&&obj.room==(string)raw["room"],"oracle furniture transform "+action);}Check(oracleModel.State.storage.Count==after["storage"].Count(),"oracle storage "+action);Check(JToken.DeepEquals(JObject.FromObject(oracleModel.Hotel().paths),after["paths"]),"oracle paths "+action);}Console.WriteLine("Godot oracle construction/maps passed");
var invalid=HotelModel.Copy(m.State);invalid.hotels[0].objects[0].x=500;Check(!HotelModel.Valid(invalid),"reject out-of-land corrupt object");invalid=HotelModel.Copy(m.State);invalid.hotels[0].paths["01,2"]=new PathState();Check(!HotelModel.Valid(invalid),"reject noncanonical path key");invalid=HotelModel.Copy(m.State);invalid.hotels[0].objects[0].room="missing-room";Check(!HotelModel.Valid(invalid),"reject corrupt room membership");invalid=HotelModel.Copy(m.State);invalid.cats[0].friend=0;Check(!HotelModel.Valid(invalid),"reject self friendship");invalid=HotelModel.Copy(m.State);invalid.hotels[0]=null;Check(!HotelModel.Valid(invalid),"reject null hotel without exception");before=JsonConvert.SerializeObject(m.State);Check(!m.Execute("place_room",P("{x:0,y:0,w:4.5,h:3}")).success,"reject fractional room dimension");Check(before==JsonConvert.SerializeObject(m.State),"malformed command rollback");
string folder=Path.Combine(Path.GetTempPath(),"parity-journal-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{string path=Path.Combine(folder,"hotel");var journal=new JournalSaveStore(path,new NewtonsoftSaveCodec());Check(journal.Save(m.State),"journal writes");m.State.coins+=10;Check(journal.Save(m.State),"journal writes second");Check(new JournalSaveStore(path,new NewtonsoftSaveCodec()).Load().coins==m.State.coins,"journal loads latest");File.WriteAllText(path+".0.save","broken");Check(new JournalSaveStore(path,new NewtonsoftSaveCodec()).Load().coins==m.State.coins-10,"journal recovers previous");}finally{foreach(var f in Directory.GetFiles(folder))File.Delete(f);Directory.Delete(folder);}ConstructionSuites.RunBuilding(Check,P,content);ConstructionSuites.RunGodMode(Check,P,content);WardrobeSuites.RunWardrobe(Check,P,content);ShellSuites.RunGrid(Check);ShellSuites.RunMigration(Check,P,content);ShellSuites.RunNavigation(Check,P,content);ShellSuites.RunGrow(Check,P,content);ShellSuites.RunShellLoadGate(Check,P,content);ShellSuites.RunRooms(Check,P,content);ShellSuites.RunInteriorEdits(Check,P,content);Console.WriteLine("PASS "+checks+" checks");}
}
